188:function Get-ThreadIdFromEvents {
189:    param([string]$Path)
190:    $text = Read-SharedText -Path $Path
191:    if (-not $text) { return '' }
192:    $uuidRe = '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
193:    foreach ($line in ($text -split "`r?`n")) {
194:        if (-not $line) { continue }
195:        $trimmed = $line.Trim()
196:        if (-not $trimmed.StartsWith('{')) { continue }
197:        $obj = $null
198:        try { $obj = $trimmed | ConvertFrom-Json } catch { continue }
199:        $type = ''
200:        if ($obj.PSObject.Properties['type']) { $type = [string]$obj.type }
201:        # primary: the "thread.started" event
202:        if ($type -ceq 'thread.started' -and $obj.PSObject.Properties['thread_id'] -and $obj.thread_id -match $uuidRe) {
203:            return [string]$obj.thread_id
204:        }
205:        # drift net 1: a top-level session-start event with a thread/session/conversation id
206:        if ($script:SessionStartEvents -ccontains $type) {
207:            foreach ($field in @('thread_id', 'session_id', 'conversation_id')) {
208:                if ($obj.PSObject.Properties[$field] -and $obj.$field -match $uuidRe) {
209:                    return [string]$obj.$field
210:                }
211:            }
212:        }
213:        # drift net 2: the older msg-wrapped shape ({"msg":{"type":"session_configured",...}})
214:        if ($obj.PSObject.Properties['msg'] -and $obj.msg -and $obj.msg.PSObject.Properties['type']) {
215:            $msg = $obj.msg
216:            if ($script:SessionStartEvents -ccontains [string]$msg.type) {
217:                foreach ($field in @('session_id', 'thread_id', 'conversation_id')) {
218:                    if ($msg.PSObject.Properties[$field] -and $msg.$field -match $uuidRe) {
219:                        return [string]$msg.$field
220:                    }
221:                }
222:            }
223:        }
224:    }
225:    return ''
226:}
