291:function Find-ThreadInRollouts {
292:    param([datetime]$StartedAt, [string]$ConsultId)
293:    $found = [pscustomobject]@{ Thread = ''; Candidate = '' }
294:    $codexHome = Get-CodexHome
295:    if (-not $codexHome) { return $found }
296:    $root = Join-Path $codexHome 'sessions'
297:    if (-not (Test-Path -LiteralPath $root)) { return $found }
298:    $days = @($StartedAt, (Get-Date)) | ForEach-Object {
299:        Join-Path (Join-Path (Join-Path $root ('{0:yyyy}' -f $_)) ('{0:MM}' -f $_)) ('{0:dd}' -f $_)
300:    } | Select-Object -Unique
301:    $candidates = @()
302:    foreach ($day in $days) {
303:        if (Test-Path -LiteralPath $day) {
304:            $candidates += Get-ChildItem -LiteralPath $day -Filter 'rollout-*.jsonl' -File -ErrorAction SilentlyContinue
305:        }
306:    }
307:    $recent = @($candidates |
308:            Where-Object { $_.LastWriteTime -ge $StartedAt.AddSeconds(-5) } |
309:            Sort-Object LastWriteTime -Descending)
310:    foreach ($file in $recent) {
311:        if ($file.Name -notmatch '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') { continue }
312:        $uuid = $Matches[1]
313:        if (-not $found.Candidate) { $found.Candidate = $uuid }
314:        if ($ConsultId -and (Read-SharedText -Path $file.FullName).IndexOf($ConsultId, [StringComparison]::OrdinalIgnoreCase) -ge 0) {
315:            $found.Thread = $uuid
316:            $found.Candidate = ''
317:            return $found
318:        }
319:    }
