2082:$script:EffortVocabularies = @{
2083:    'openai' = @{ Mapping = 'openai'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'xhigh' } }
2084:    'zai'    = @{ Mapping = 'zai-v1'; Map = @{ 'low' = 'low'; 'medium' = 'high'; 'high' = 'high'; 'xhigh' = 'max' } }
2085:}
2086:$script:EffortHosts = @{ 'builtin:openai' = 'openai'; 'api.openai.com' = 'openai'; 'api.z.ai' = 'zai'; 'open.bigmodel.cn' = 'zai' }
