2088:# { Requested; Sent; Mapping; Basis; Error }
2089:function Resolve-EffortPlan {
2090:    param($Identity, [string]$Requested, [string]$Native = '')
2091:    $plan = [pscustomobject]@{ Requested = $Requested; Sent = ''; Mapping = ''; Basis = ''; Error = '' }
2092:    if ($Native) {
2093:        $plan.Requested = $Native; $plan.Sent = $Native; $plan.Mapping = 'native'; $plan.Basis = '-NativeEffort, sent verbatim'
2094:        return $plan
2095:    }
2096:    $vocab = ''
2097:    $hostName = [string]$Identity.HostName
2098:    if ($hostName -and $script:EffortHosts.ContainsKey($hostName)) {
2099:        $vocab = $script:EffortHosts[$hostName]; $plan.Basis = "host $hostName"
2100:    } elseif ($Identity.ModelSource -ne 'unknown') {
2101:        $m = ([string]$Identity.Model).ToLowerInvariant()
2102:        if ($m.StartsWith('glm-')) { $vocab = 'zai'; $plan.Basis = 'model prefix glm-' }
2103:        elseif ($m.StartsWith('gpt-')) { $vocab = 'openai'; $plan.Basis = 'model prefix gpt-' }
2104:        elseif ($m -match '^o[0-9]') { $vocab = 'openai'; $plan.Basis = 'model prefix o<digit>' }
2105:    }
2106:    if (-not $vocab) {
2107:        $hostLabel = if ($hostName) { $hostName } else { 'unknown-host' }
2108:        $plan.Error = "no effort vocabulary known for $hostLabel/$($Identity.Model); pass -NativeEffort <value> to send a value verbatim"
2109:        return $plan
2110:    }
2111:    $v = $script:EffortVocabularies[$vocab]
2112:    $plan.Sent = $v.Map[$Requested]
2113:    $plan.Mapping = $v.Mapping
2114:    return $plan
2115:}
