2117:# ----------------------------------------------------------------------------- peak windows
2118:#
2119:# CODEX_CONSULT_PEAK_<PROVIDER> = "<days> <HH:MM>-<HH:MM> <+HH:MM|-HH:MM>" (the provider
2120:# name upper-cased, every character outside A-Z 0-9 replaced by _), e.g.
2121:# CODEX_CONSULT_PEAK_ZAI="Mon-Fri 14:00-18:00 +08:00". Days: *, a day (Mon), a range
2122:# (Mon-Fri; it may wrap: Fri-Mon) or a comma list of those. Optional
2123:# CODEX_CONSULT_PEAK_<PROVIDER>_EXCEPT = comma-separated YYYY-MM-DD or
2124:# YYYY-MM-DD..YYYY-MM-DD: those calendar dates (in the schedule's offset) are off-peak all
2125:# day. Evaluated ONCE at launch in the fixed offset: start inclusive, end exclusive (24:00
2126:# = midnight); an overnight window (start > end) spans midnight and its day check applies
2127:# to the day it STARTED. peak = $true | $false; $null = no schedule (unknown). A long
2128:# consultation that starts off-peak may still run into the window.
2129:$script:DayNames = @('sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat')
2130:
2131:function Get-PeakVariableName {
2132:    param([string]$Provider)
2133:    return ('CODEX_CONSULT_PEAK_' + ($Provider.ToUpperInvariant() -replace '[^A-Z0-9]', '_'))
2134:}
