2136:# { Days (bool[7], index = [int][DayOfWeek]); Start; End (minutes); Offset; Error }
2137:function ConvertFrom-PeakSpec {
2138:    param([string]$Spec, [string]$VarName)
2139:    $r = [pscustomobject]@{ Days = $null; Start = 0; End = 0; Offset = [TimeSpan]::Zero; Error = '' }
2140:    $format = "expected '<days> <HH:MM>-<HH:MM> <+HH:MM|-HH:MM>', e.g. 'Mon-Fri 14:00-18:00 +08:00'"
2141:    $trimmed = ([string]$Spec).Trim()
2142:    $tokens = @($trimmed -split '\s+')
2143:    if ($tokens.Count -ne 3) {
2144:        $r.Error = "$VarName='$Spec' is malformed: bad token '$trimmed' ($($tokens.Count) field(s) instead of 3); $format"
2145:        return $r
2146:    }
2147:    $dayHelp = 'day names are Mon Tue Wed Thu Fri Sat Sun, a range Mon-Fri, a list Mon,Wed or *'
2148:    $days = New-Object 'bool[]' 7
2149:    if ($tokens[0] -eq '*') {
2150:        for ($d = 0; $d -lt 7; $d++) { $days[$d] = $true }
2151:    } else {
2152:        foreach ($item in $tokens[0].Split(',')) {
2153:            $mRange = [regex]::Match($item, '^([A-Za-z]{3})-([A-Za-z]{3})$')
2154:            if ($mRange.Success) {
2155:                $a = [Array]::IndexOf($script:DayNames, $mRange.Groups[1].Value.ToLowerInvariant())
2156:                $b = [Array]::IndexOf($script:DayNames, $mRange.Groups[2].Value.ToLowerInvariant())
2157:                if ($a -lt 0 -or $b -lt 0) { $r.Error = "$VarName='$Spec' is malformed: bad token '$item' ($dayHelp); $format"; return $r }
2158:                $d = $a
2159:                while ($true) { $days[$d] = $true; if ($d -eq $b) { break }; $d = ($d + 1) % 7 }
2160:                continue
2161:            }
2162:            $one = -1
2163:            if ($item -match '^[A-Za-z]{3}$') { $one = [Array]::IndexOf($script:DayNames, $item.ToLowerInvariant()) }
2164:            if ($one -lt 0) { $r.Error = "$VarName='$Spec' is malformed: bad token '$item' ($dayHelp); $format"; return $r }
2165:            $days[$one] = $true
2166:        }
2167:    }
2168:    $mt = [regex]::Match($tokens[1], '^([0-9]{2}):([0-9]{2})-([0-9]{2}):([0-9]{2})$')
2169:    $timeOk = $mt.Success
2170:    if ($timeOk) {
2171:        $sh = [int]$mt.Groups[1].Value; $sm = [int]$mt.Groups[2].Value; $eh = [int]$mt.Groups[3].Value; $em = [int]$mt.Groups[4].Value
2172:        $timeOk = ($sh -le 23 -and $sm -le 59 -and $em -le 59 -and ($eh -le 23 -or ($eh -eq 24 -and $em -eq 0)))
2173:        if ($timeOk) {
2174:            $r.Start = $sh * 60 + $sm
2175:            $r.End = $eh * 60 + $em
2176:            if ($r.Start -eq $r.End) { $timeOk = $false }
2177:        }
2178:    }
2179:    if (-not $timeOk) { $r.Error = "$VarName='$Spec' is malformed: bad token '$($tokens[1])' (a window HH:MM-HH:MM, 00:00..23:59, end up to 24:00, start <> end); $format"; return $r }
2180:    $mo = [regex]::Match($tokens[2], '^([+-])([0-9]{2}):([0-9]{2})$')
2181:    $offOk = $mo.Success
2182:    if ($offOk) {
2183:        $oh = [int]$mo.Groups[2].Value; $om = [int]$mo.Groups[3].Value
2184:        $offOk = ($om -le 59 -and ($oh * 60 + $om) -le 14 * 60)
2185:        if ($offOk) {
2186:            $r.Offset = New-Object TimeSpan($oh, $om, 0)
2187:            if ($mo.Groups[1].Value -eq '-') { $r.Offset = $r.Offset.Negate() }
2188:        }
2189:    }
2190:    if (-not $offOk) { $r.Error = "$VarName='$Spec' is malformed: bad token '$($tokens[2])' (a UTC offset +HH:MM or -HH:MM, at most 14:00); $format"; return $r }
2191:    $r.Days = $days
2192:    return $r
2193:}
