2195:# { Dates (set of 'yyyy-MM-dd'); Error }
2196:function ConvertFrom-PeakExceptions {
2197:    param([string]$Text, [string]$VarName)
2198:    $set = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
2199:    $r = [pscustomobject]@{ Dates = $set; Error = '' }
2200:    $format = 'expected comma-separated YYYY-MM-DD or YYYY-MM-DD..YYYY-MM-DD'
2201:    foreach ($raw in ([string]$Text).Split(',')) {
2202:        $item = $raw.Trim()
2203:        if (-not $item) { continue }
2204:        $parts = @($item -split '\.\.')
2205:        $parsed = New-Object System.Collections.Generic.List[datetime]
2206:        foreach ($p in $parts) {
2207:            $dt = [datetime]::MinValue
2208:            if ($p -notmatch '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' -or -not [datetime]::TryParseExact($p, 'yyyy-MM-dd', $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dt)) {
2209:                $r.Error = "$VarName='$Text' is malformed: bad token '$item' ($format)"; return $r
2210:            }
2211:            $parsed.Add($dt)
2212:        }
2213:        if ($parsed.Count -gt 2 -or ($parsed.Count -eq 2 -and $parsed[1] -lt $parsed[0])) {
2214:            $r.Error = "$VarName='$Text' is malformed: bad token '$item' ($format; a range must not run backwards)"; return $r
2215:        }
2216:        $d = $parsed[0]
2217:        $last = $parsed[$parsed.Count - 1]
2218:        $guard = 0
2219:        while ($d -le $last -and $guard -lt 3700) { [void]$set.Add($d.ToString('yyyy-MM-dd', $script:Invariant)); $d = $d.AddDays(1); $guard++ }
2220:    }
2221:    return $r
2222:}
