2224:# { Peak ($true | $false | $null); Schedule; Source ('env'|'none'); Variable; Local;
2225:#   Detail; Error }. -Spec / -Except replace the environment (tests).
2226:function Get-PeakStatus {
2227:    param([string]$Provider, [datetime]$UtcNow = [datetime]::UtcNow, [string]$Spec = $null, [string]$Except = $null)
2228:    $st = [pscustomobject]@{ Peak = $null; Schedule = ''; Source = 'none'; Variable = ''; Local = ''; Detail = 'no schedule'; Error = '' }
2229:    if (-not $Provider) { $st.Detail = 'provider unknown'; return $st }
2230:    $var = Get-PeakVariableName $Provider
2231:    $st.Variable = $var
2232:    if (-not $PSBoundParameters.ContainsKey('Spec')) { $Spec = [Environment]::GetEnvironmentVariable($var) }
2233:    if (-not $PSBoundParameters.ContainsKey('Except')) { $Except = [Environment]::GetEnvironmentVariable($var + '_EXCEPT') }
2234:    if (-not $Spec -or -not $Spec.Trim()) { return $st }
2235:    $parsed = ConvertFrom-PeakSpec -Spec $Spec -VarName $var
2236:    if ($parsed.Error) { $st.Error = $parsed.Error; return $st }
2237:    $exceptions = $null
2238:    if ($Except -and $Except.Trim()) {
2239:        $exceptions = ConvertFrom-PeakExceptions -Text $Except -VarName ($var + '_EXCEPT')
2240:        if ($exceptions.Error) { $st.Error = $exceptions.Error; return $st }
2241:    }
2242:    $st.Source = 'env'
2243:    $st.Schedule = $Spec.Trim()
2244:    if ($exceptions) { $st.Schedule += "; except $($Except.Trim())" }
2245:    $utc = $UtcNow
2246:    if ($utc.Kind -eq [DateTimeKind]::Local) { $utc = $utc.ToUniversalTime() }
2247:    $local = $utc.Add($parsed.Offset)
2248:    $sign = if ($parsed.Offset -lt [TimeSpan]::Zero) { '-' } else { '+' }
2249:    $st.Local = $local.ToString('yyyy-MM-dd HH:mm ddd', $script:Invariant) + " $sign" + $parsed.Offset.Duration().ToString('hh\:mm', $script:Invariant)
2250:    $tod = $local.TimeOfDay.TotalMinutes
2251:    $dow = [int]$local.DayOfWeek
2252:    $prev = ($dow + 6) % 7
2253:    if ($parsed.Start -lt $parsed.End) {
2254:        $inside = ($parsed.Days[$dow] -and $tod -ge $parsed.Start -and $tod -lt $parsed.End)
2255:    } else {
2256:        $inside = (($parsed.Days[$dow] -and $tod -ge $parsed.Start) -or ($parsed.Days[$prev] -and $tod -lt $parsed.End))
2257:    }
2258:    $dateKey = $local.ToString('yyyy-MM-dd', $script:Invariant)
2259:    if ($exceptions -and $exceptions.Dates.Contains($dateKey)) {
2260:        $st.Peak = $false
2261:        $st.Detail = "exception date $dateKey (off-peak all day)"
2262:    } elseif ($inside) {
2263:        $st.Peak = $true
2264:        $st.Detail = 'inside the peak window'
2265:    } else {
2266:        $st.Peak = $false
2267:        $st.Detail = 'outside the peak window'
2268:    }
2269:    return $st
2270:}
