2295:# { Mode; Parent; ParentN; Note; Error }. $Mode '' = automatic.
2296:function Select-ParentThread {
2297:    param([object[]]$Consults, $Identity, [string]$Mode, [string]$Thread)
2298:    $r = [pscustomobject]@{ Mode = $Mode; Parent = ''; ParentN = $null; Note = ''; Error = '' }
2299:    $entries = @($Consults | Where-Object { $null -ne $_ })
2300:    $lineage = $Identity.Lineage
2301:    $unresolvedMsg = "provider identity could not be resolved ($($Identity.Note)); pass -Provider and -Model explicitly, or use -Mode new"
2302:    $driftMsg = { param($t, $n, $fp) "endpoint or protocol of provider $($Identity.Provider) changed since thread $t (consult n=$n recorded provider fingerprint $(Format-ShortHash $fp), now $(Format-ShortHash $Identity.Fingerprint)); start a new thread with -Mode new" }
2303:    $thread = ([string]$Thread).Trim()
2304:    if ($thread) {
2305:        if ($Mode -eq 'new') { $r.Error = '-Thread needs -Mode fork or resume (-Mode new always starts a fresh thread).'; return $r }
2306:        if (-not $Identity.Resolved) { $r.Error = $unresolvedMsg; return $r }
2307:        $match = $null
2308:        for ($i = $entries.Count - 1; $i -ge 0; $i--) {
2309:            if ([string](Get-PropertyValue $entries[$i] 'thread' '') -eq $thread) { $match = $entries[$i]; break }
2310:        }
2311:        if (-not $match) {
2312:            $cand = $null
2313:            for ($i = $entries.Count - 1; $i -ge 0; $i--) {
2314:                if ([string](Get-PropertyValue $entries[$i] 'thread_candidate' '') -eq $thread) { $cand = $entries[$i]; break }
2315:            }
2316:            if ($cand) { $r.Error = "thread $thread has unknown provenance: it is only an unverified rollout candidate of consult n=$(Get-PropertyValue $cand 'n' '?') (that rollout did not contain the run's consultation id); use -Mode new" }
2317:            else { $r.Error = "thread $thread has unknown provenance: it is not in this task's ledger; use -Mode new" }
2318:            return $r
2319:        }
2320:        $n = Get-PropertyValue $match 'n' '?'
2321:        if ($null -eq (Get-PropertyValue $match 'reviewer' $null)) {
2322:            $r.Error = "thread $thread has unknown provenance (recorded before 0.3.0); use -Mode new"; return $r
2323:        }
2324:        $fp = Get-EntryFingerprint $match
2325:        $theirs = [string](Get-PropertyValue $match 'lineage' '')
2326:        if (-not $fp) {
2327:            $r.Error = "thread $thread has unknown provenance: consult n=$n ran with an unresolved reviewer identity ($theirs); use -Mode new"; return $r
2328:        }
2329:        if ($theirs -cne $lineage) {
2330:            $r.Error = "thread $thread belongs to lineage $theirs (consult n=$n); this run is $lineage. A thread never changes provider or model: use -Mode new, or run as $theirs"; return $r
2331:        }
2332:        if ($fp -ne $Identity.Fingerprint) { $r.Error = (& $driftMsg $thread $n $fp); return $r }
2333:        if (-not $r.Mode) { $r.Mode = 'fork' }
2334:        $r.Parent = $thread
2335:        $r.ParentN = $n
2336:        $r.Note = "-Thread, lineage $lineage (consult n=$n)"
2337:        return $r
2338:    }
2339:    if (-not $Identity.Resolved) {
2340:        if ($Mode -eq 'fork' -or $Mode -eq 'resume') { $r.Error = $unresolvedMsg; return $r }
2341:        $r.Mode = 'new'
2342:        $r.Note = "reviewer identity unresolved, automatic fork/resume is off ($($Identity.Note))"
2343:        return $r
2344:    }
2345:    $parent = $null
2346:    $legacy = 0; $unresolved = 0; $candidates = 0
2347:    $others = New-Object System.Collections.Generic.List[string]
2348:    for ($i = $entries.Count - 1; $i -ge 0; $i--) {
2349:        $c = $entries[$i]
2350:        $t = [string](Get-PropertyValue $c 'thread' '')
2351:        if (-not $t) {
2352:            if ([string](Get-PropertyValue $c 'thread_candidate' '')) { $candidates++ }
2353:            continue
2354:        }
2355:        if ($null -eq (Get-PropertyValue $c 'reviewer' $null)) { $legacy++; continue }
2356:        if (-not (Get-EntryFingerprint $c)) { $unresolved++; continue }
2357:        $l = [string](Get-PropertyValue $c 'lineage' '')
2358:        if ($l -cne $lineage) { if (-not $others.Contains($l)) { $others.Add($l) }; continue }
2359:        if (-not $parent) { $parent = $c }
2360:    }
2361:    if ($parent) {
2362:        if ($Mode -eq 'new') { return $r }
2363:        $pt = [string]$parent.thread
2364:        $n = Get-PropertyValue $parent 'n' '?'
2365:        $fp = Get-EntryFingerprint $parent
2366:        if ($fp -ne $Identity.Fingerprint) { $r.Error = (& $driftMsg $pt $n $fp); return $r }
2367:        if (-not $r.Mode) { $r.Mode = 'fork' }
2368:        $r.Parent = $pt
2369:        $r.ParentN = $n
2370:        $r.Note = "newest thread of lineage $lineage (consult n=$n)"
2371:        return $r
2372:    }
2373:    $why = New-Object System.Collections.Generic.List[string]
2374:    if ($legacy -gt 0) { $why.Add("$legacy thread(s) recorded before 0.3.0 have unknown provenance and are never automatic parents") }
2375:    if ($others.Count -gt 0) { $why.Add("other lineage(s): $($others -join ', ')") }
2376:    if ($unresolved -gt 0) { $why.Add("$unresolved thread(s) of runs with an unresolved reviewer identity are never parents") }
2377:    if ($candidates -gt 0) { $why.Add("$candidates unverified rollout candidate(s) are never parents") }
2378:    $note = "no thread of lineage $lineage in this task's ledger"
2379:    if ($why.Count -gt 0) { $note += '; ' + ($why.ToArray() -join '; ') }
2380:    if ($Mode -eq 'fork' -or $Mode -eq 'resume') {
2381:        $r.Error = "-Mode $Mode needs a parent thread: $note. Pass -Thread <uuid> of lineage $lineage, or use -Mode new"
2382:        return $r
2383:    }
2384:    $r.Mode = 'new'
2385:    if ($entries.Count -gt 0) { $r.Note = $note }
2386:    return $r
2387:}
